    public ComponentInfo call_T0_KreditneKartice(String instrument_id, ComponentInfo komponenta) throws JsonProcessingException, SQLException {

        System.out.println("poziva call_T0_KreditneKartice ");
        String account = null;
        String pan = null;
        int secondHyphenIndex = instrument_id.indexOf('-', instrument_id.indexOf('-') + 1);
        int thirdHyphenIndex = instrument_id.indexOf('-', secondHyphenIndex + 1);

        if (secondHyphenIndex != -1 && thirdHyphenIndex != -1) {
            pan = instrument_id.substring(secondHyphenIndex + 1, thirdHyphenIndex);
            System.out.println("Extracted pan: " + pan);
        }
        Connection con = DriverManager.getConnection
                (databaseUrl, databaseUser, databasePassword);
        try {
            Statement statement = con.createStatement();
            String query = "select to_number(f10) as account_number from as400.bec4ariusf where f1= '" + pan + "'";
            ResultSet resultSet = statement.executeQuery(query);
            while (resultSet.next()) {
                account = resultSet.getString("account_number");
                System.out.println("Account iz upita za KK : " + account);
            }
            resultSet.close();
            statement.close();
            con.close();
        } catch (Exception e) {
            con.close();
            System.out.println("greska: " + e);
        }

        System.out.println("Racun za koji pozivamo servis za kreditne kartice : " + account);
        // Provera i dodavanje vodeÄ‡ih nula ako je duÅ¾ina manja od 11
        if (account.length() < 11) {
            account = String.format("%011d", Long.parseLong(account));
        }
        System.out.println("Racun za koji pozivamo servis za kreditne kartice sa vodecim nulama : " + account);
        RestTemplate restTemplate = new RestTemplate();
        // String url = "http://srvcmstestac:9080/TaseeRestApiServices/rest/cmsdata/account/" + account;
        String url = tasUrl + account;
        ResponseEntity<String> call = restTemplate.getForEntity(url, String.class);
        ObjectMapper objectMapper = new ObjectMapper();
        CC_Balance_Response cc_balance_response = null;
        try {
            cc_balance_response = objectMapper.readValue(
                    call.getBody(), CC_Balance_Response.class);
        } catch (Exception e) {
            System.out.println("greska u servisu za kreditne kartice T-0 : " + e);
        }

        if (cc_balance_response.getAccountNumber() != null && cc_balance_response.getUkd() != null) {
            BigDecimal ukd = new BigDecimal(cc_balance_response.getUkd()).negate();
            BigDecimal ngl = new BigDecimal(cc_balance_response.getNgl()).negate();
            BigDecimal avu = new BigDecimal(cc_balance_response.getAvu()).negate();
            BigDecimal rez = new BigDecimal(cc_balance_response.getRez()).negate();
            BigDecimal nrt = new BigDecimal(cc_balance_response.getNrt()).negate();
            BigDecimal dgl = new BigDecimal(cc_balance_response.getDgl()).negate();
            BigDecimal drt = new BigDecimal(cc_balance_response.getDrt()).negate();
            BigDecimal nrk = new BigDecimal(cc_balance_response.getNrk()).negate();
            BigDecimal drk = new BigDecimal(cc_balance_response.getDrk()).negate();
            BigDecimal nzk = new BigDecimal(cc_balance_response.getNzk()).negate();
            BigDecimal dzk = new BigDecimal(cc_balance_response.getDzk()).negate();
            BigDecimal dnk = new BigDecimal(cc_balance_response.getDnk()).negate();
            BigDecimal ncl = new BigDecimal(cc_balance_response.getNcl()).negate();
            BigDecimal lim = new BigDecimal(cc_balance_response.getLim()).negate();
            // menjam komponentu
            ComponentInfo novaKomponenta = komponenta;
            novaKomponenta.setAccount(account);
            String componentCode = komponenta.getComponentCode();
            switch (componentCode) {
                case "UNDPRINC":
                    novaKomponenta.setAmountRSD(ngl.add(avu).add(rez));
                    novaKomponenta.setAmountAccrRSD(nrt.add(nrk));
                    novaKomponenta.setAmount(ngl.add(avu).add(rez));
                    novaKomponenta.setAmountAccr(nrt.add(nrk));
                    break;
                case "ODUEPRINC":
                    novaKomponenta.setAmountRSD(dgl.add(drt));
                    novaKomponenta.setAmount(dgl.add(drt));
                    break;
                case "ODUEINT":
                    novaKomponenta.setAmountRSD(drk);
                    novaKomponenta.setAmountAccrRSD(nzk);
                    novaKomponenta.setAmount(drk);
                    novaKomponenta.setAmountAccr(nzk);
                    break;
                case "PENINT":
                    novaKomponenta.setAmountRSD(dzk);
                    novaKomponenta.setAmount(dzk);
                    break;
                case "FEE":
                    novaKomponenta.setAmountRSD(dnk);
                    novaKomponenta.setAmountAccrRSD(ncl);
                    novaKomponenta.setAmount(dnk);
                    novaKomponenta.setAmountAccr(ncl);
                    break;
                case "UND":
                    BigDecimal undResult = lim.subtract(ngl);
                    System.out.println("UND calc: lim=" + lim + ", ngl=" + ngl + ", result=" + undResult);
                    // ako je rezultat veci od nule postavi na NULU
                    if (undResult.compareTo(BigDecimal.ZERO) > 0) {
                        undResult = BigDecimal.ZERO;
                    }
//                    novaKomponenta.setAmountRSD(lim.subtract(ukd));
//                    novaKomponenta.setAmount(lim.subtract(ukd));
                    novaKomponenta.setAmountRSD(undResult);
                    novaKomponenta.setAmount(undResult);
                    break;
                default:
                    System.out.println("Nepoznata komponenta");
            }
            return novaKomponenta;
        } else
            return komponenta;
    }

